/*Table structure for table `associated_parking_lot` */

DROP TABLE IF EXISTS `associated_parking_lot`;

CREATE TABLE `associated_parking_lot` (
  `id` int(11) NOT NULL COMMENT '主键',
  `parking_lot_number` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '车场编号',
  `parking_lot_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '车场名称',
  `associated_time` datetime DEFAULT NULL COMMENT '关联时间',
  `association_status` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联状态',
  `associated_person` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联人',
  `create_username` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建者用户名称(对应登录用户的username)',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_username` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '最后修改者用户名称(对应登录用户的username)',
  `update_time` datetime DEFAULT NULL COMMENT '最后修改时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Associated parking lot table, includes fields: id, parking_lot_number, parking_lot_name, associated_time, association_status, associated_person.';

