/*Table structure for table `billing_detail` */

DROP TABLE IF EXISTS `billing_detail`;

CREATE TABLE `billing_detail` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `order_id` int(11) DEFAULT NULL COMMENT '订单ID',
  `serial_number` int(11) DEFAULT NULL COMMENT '序号',
  `billing_type` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '计费类型',
  `billing_vehicle` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '计费车辆',
