  `update_username` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '最后修改者用户名称(对应登录用户的username)',
  `update_time` datetime DEFAULT NULL COMMENT '最后修改时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2298 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='计费明细表，包含订单ID、序号、计费类型、计费车辆、计费时段、开始时间、结束时间、时长和计费规则。';

