/*Table structure for table `billing_scheme` */

DROP TABLE IF EXISTS `billing_scheme`;

CREATE TABLE `billing_scheme` (
  `id` int(11) NOT NULL COMMENT '主键',
  `scheme_type` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '收费方案类型',
  `free_duration` int(11) DEFAULT NULL COMMENT '免费时长',
  `temporary_car` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '临时车',
  `stored_value_car` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '储值车',
  `new_energy_free_duration` int(11) DEFAULT NULL COMMENT '新能源免费时长',
  `free_duration_reduction` int(11) DEFAULT NULL COMMENT '免费时长减免',
  `white_plate_car_free` tinyint(1) DEFAULT NULL COMMENT '白牌车免费',
  `new_energy_free_times` int(11) DEFAULT NULL COMMENT '新能源免费次数',
  `free_period_reduction` int(11) DEFAULT NULL COMMENT '免费时段减免',
  `temporary_car_first_tier` int(11) DEFAULT NULL COMMENT '临时车-第一阶梯',
  `temporary_car_second_tier` int(11) DEFAULT NULL COMMENT '临时车-第二阶梯',
  `temporary_car_third_tier` int(11) DEFAULT NULL COMMENT '临时车-第三阶梯',
  `stored_value_car_first_tier` int(11) DEFAULT NULL COMMENT '储值车-第一阶梯',
  `stored_value_car_second_tier` int(11) DEFAULT NULL COMMENT '储值车-第二阶梯',
  `stored_value_car_third_tier` int(11) DEFAULT NULL COMMENT '储值车-第三阶梯',
  `temporary_car_cap_amount` decimal(10,2) DEFAULT NULL COMMENT '临时车-封顶金额',
  `stored_value_car_cap_amount` decimal(10,2) DEFAULT NULL COMMENT '储值车-封顶金额',
  `create_username` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建者用户名称(对应登录用户的username)',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_username` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '最后修改者用户名称(对应登录用户的username)',
  `update_time` datetime DEFAULT NULL COMMENT '最后修改时间',
  `segment_charging` tinyint(1) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='收费方案表，包含收费方案类型、免费时长、临时车、储值车、新能源免费时长、免费时长减免、白牌车免费、新能源免费次数、免费时段减免、临时车-第一阶梯、临时车-第二阶梯、临时车-第三阶梯、储值车-第一阶梯、储值车-第二阶梯、储值车-第三阶梯、临时车-封顶金额、储值车-封顶金额。';

