  `abnormal_status_other` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '异常车状态:其他',
  `abnormal_handling_duplicate` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '异常车处理:重复入场',
